-- Curated public authoring documentation. Executable bodies are extracted from
-- the actual addon functions; this file must never contain copied Lua bodies.
return {
 Platform_GetItemInfoInstant={module='Platform/items.lua',member='Platform.GetItemInfoInstant',callName='addon.Platform:GetItemInfoInstant',description='Read normalized native item classification metadata. The record contains canonical itemID, classID and subClassID; it does not require loaded item display text. Missing, failed, malformed or restricted metadata returns nil with a reason.',args={self={type='RMPlatform',description='Rotation Master platform adapter (implicit with colon calls).'},item={type='number | string',description='Positive item ID or native-recognized item name/link to classify.'}},returns={{type='table | nil',description='Readable canonical item classification record, or nil when unavailable.'},{type='string | nil',description='Validation or availability reason for a nil result.'}}},
 Platform_GetGroupMembership={module='Platform/groups.lua',member='Platform.GetGroupMembership',callName='addon.Platform:GetGroupMembership',description='Read public group membership on identified client families. Unknown clients are unsupported. True raidOnly checks IsInRaid; false or nil checks IsInGroup using its native default group category. A readable false result stays false. Missing, failed, malformed or restricted observations return nil with a reason.',args={self={type='RMPlatform',description='Rotation Master platform adapter (implicit with colon calls).'},raidOnly={type='boolean | nil',description='True requests raid membership; false or nil requests any group membership.'}},returns={{type='boolean | nil',description='Observed membership, or nil when unavailable.'},{type='string | nil',description='Validation or availability reason for a nil result.'}}},
 Platform_GetGlyphItemInfo={module='Platform/glyphs.lua',member='Platform.GetGlyphItemInfo',callName='addon.Platform:GetGlyphItemInfo',description='Classify a numeric item as a glyph for the requested class, using guarded native item metadata. Class is optional and defaults to the readable player class. This establishes item classification only, not equipped status or an item-to-glyph-spell ID mapping.',args={self={type='RMPlatform',description='Rotation Master platform adapter (implicit with colon calls).'},itemID={type='number',description='Positive integer glyph item ID stored by the condition; arrays, item-set keys and spell IDs are not item references.'},classID={type='number | nil',description='Optional positive class ID; nil queries the current player class under protection.'}},returns={{type='table | nil',description='Readable canonical itemID/classID/subClassID record when the item is a glyph for the requested class; nil for invalid or unavailable metadata.'},{type='string | nil',description='Classification, validation or availability reason for a nil result.'}}},
 Platform_GetGlyphSocketSnapshot={module='Platform/glyphs.lua',member='Platform.GetGlyphSocketSnapshot',callName='addon.Platform:GetGlyphSocketSnapshot',description='Observe glyph sockets on verified Wrath, Cata and Mists client layouts. Returns slots and a complete flag. Each slot has active=false when known locked or empty, active=true plus spellID when occupied, or nil active plus reason when unavailable. Unknown layouts and failed count queries return nil with a reason. This does not compare item names or prove exact item-to-spell identity.',args={self={type='RMPlatform',description='Rotation Master platform adapter (implicit with colon calls).'}},returns={{type='table | nil',description='Normalized bounded socket snapshot with slots and complete, or nil when the query is unavailable.'},{type='string | nil',description='Policy, validation or availability reason for a nil snapshot.'}}},
    Platform_GetUnitCastObservation={module='Platform/casting.lua',member='Platform.GetUnitCastObservation',callName='addon.Platform:GetUnitCastObservation',description='Observe a unit casting or channeling on supported readable clients. A readable inactive result returns active=false. Active records contain name and independently available remainingSeconds and interruptible fields, with remainingReason or interruptibleReason when an optional field is unavailable. Missing, failed or restricted observations return nil with a reason.',args={self={type='RMPlatform',description='Rotation Master platform adapter (implicit with colon calls).'},unit={type='string',description='Unit token whose current cast or channel should be observed.'},kind={type='string',description='Observation kind: cast or channel. These use different native interruptibility tuple positions.'}},returns={{type='table | nil',description='Fresh readable record with active, optional name, remainingSeconds and interruptible. Remaining time is in seconds and is clamped to zero. An unavailable optional field has its own reason; it does not invalidate a readable active name.'},{type='string | nil',description='Availability or query-validation reason when the whole observation is unavailable.'}}},
    Platform_GetNameplateMaxDistance={module='Platform/range.lua',member='Platform.GetNameplateMaxDistance',callName='addon.Platform:GetNameplateMaxDistance',description='Read the current positive nameplate visibility distance using the supported CVar API. This limits a Distance Count query; it does not prove that all nearby units have been observed. Missing, malformed, restricted or failed observations return nil with a reason.',args={self={type='RMPlatform',description='Rotation Master platform adapter (implicit with colon calls).'}},returns={{type='number | nil',description='Current positive visibility distance in yards; nil when unavailable.'},{type='string | nil',description='Availability reason for a nil result.'}}},
    Platform_GetRangeCheckBounds={module='Platform/range.lua',member='Platform.GetRangeCheckBounds',callName='addon.Platform:GetRangeCheckBounds',description='Read the public LibRangeCheck interval for a unit. A successful upper bound is inclusive; a positive failed lower bound is strict. A zero lower floor is synthetic. Neither bound is an exact distance, and a missing upper bound is not proof that the unit is outside every radius. Unavailable, malformed, restricted or failed observations return nil with a reason.',args={self={type='RMPlatform',description='Rotation Master platform adapter (implicit with colon calls).'},unit={type='string',description='Current unit token whose distance from the player should be observed.'}},returns={{type='table | nil',description='Readable interval with optional minimum and maximum bounds in yards. At least one bound is present; nil when unavailable.'},{type='string | nil',description='Availability or validation reason for a nil result.'}}},
    Platform_IsAutoRepeatActive={module='Platform/spells.lua',member='Platform.IsAutoRepeatActive',callName='addon.Platform:IsAutoRepeatActive',description='Read the player auto-repeat state for a spell such as Shoot or Auto Shot. This is distinct from a current or queued cast. Modern clients receive the exact spell ID; a legacy query resolves the player spell-book slot first. Restricted client policies, unreadable results and unavailable book slots return nil with a reason. This observes state and never starts or stops a spell.',args={self={type='RMPlatform',description='Rotation Master platform adapter (implicit with colon calls).'},spellID={type='number',description='Positive integer spell ID, not a spell-book slot.'}},returns={{type='boolean | nil',description='True when the client reports this spell auto-repeating; false when it reports inactive; nil when unavailable.'},{type='string | nil',description='Validation or availability reason for a nil result.'}}},
    Widget_GetSpellId={module='Conditions/common.lua',callName='addon:Widget_GetSpellId',description='Resolve the spell identifier stored by a condition. With exact rank enabled the supplied ID is retained; otherwise ranked Classic clients resolve the currently known rank through the spell catalog. Returns nil and an availability reason if resolution cannot be completed.',args={self={type='RMAddon',description='Rotation Master addon instance (implicit with colon calls).'},spellid={type='number',description='Stored spell ID to resolve.'},ranked={type='boolean | nil',description='True to require this exact rank; false or nil follows the available rank.'}},returns={{type='number | nil',description='Resolved spell ID, or nil when unavailable.'},{type='string | nil',description='Availability reason when resolution fails; nil on success.'}}},
    Platform_IsSpellReady={module='Platform/spells.lua',member='Platform.IsSpellReady',callName='addon.Platform:IsSpellReady',description='Check whether a spell can be recommended now, allowing a spell whose remaining cooldown ends with the current global cooldown. This checks cooldown readiness only; it does not check learned status, range or resource usability. Pass evaluation time from evalStart or GetTime().',args={self={type='RMPlatform',description='Rotation Master platform adapter. A dot reference requires addon.Platform as the first argument; a colon call supplies it implicitly.'},spell={type='number | string',description='Spell ID or client-recognized spell name whose cooldown should be checked.'},now={type='number',description='Current evaluation time in seconds from GetTime(), normally evalStart.'}},returns={{type='boolean | nil',description='True when ready by the end of the global cooldown; false when its own cooldown prevents recommendation; nil when the client cannot supply a readable result.'},{type='string | nil',description='Availability or validation reason when the result is nil.'}}},
    Platform_GetSpellCooldown={module='Platform/spells.lua',member='Platform.GetSpellCooldown',callName='addon.Platform:GetSpellCooldown',description='Read and normalize a spell cooldown across supported clients. The returned record contains startTime, duration, isEnabled and modRate. The timestamps and duration already describe expiration in GetTime() seconds; do not divide them by modRate.',args={self={type='RMPlatform',description='Rotation Master platform adapter. A dot reference requires addon.Platform as the first argument; a colon call supplies it implicitly.'},spell={type='number | string',description='Spell ID or client-recognized spell name whose cooldown should be read.'}},returns={{type='table | nil',description='Readable cooldown record, or nil when unavailable.'},{type='string | nil',description='Availability or validation reason when the record is nil.'}}},
    Platform_GetSpellCharges={module='Platform/spells.lua',member='Platform.GetSpellCharges',callName='addon.Platform:GetSpellCharges',description='Read a normalized charge record: currentCharges, maxCharges, cooldownStartTime, cooldownDuration, chargeModRate and isActive. Unsupported spells or restricted client data return nil with a reason.',args={self={type='RMPlatform',description='Rotation Master platform adapter. A dot reference requires addon.Platform as the first argument; a colon call supplies it implicitly.'},spell={type='number | string',description='Spell ID or client-recognized spell name whose charges should be read.'}},returns={{type='table | nil',description='Readable charge record, or nil when unavailable.'},{type='string | nil',description='Availability or validation reason when the record is nil.'}}},
    Platform_GetSpellRangeState={module='Platform/actions.lua',member='Platform.GetSpellRangeState',callName='addon.Platform:GetSpellRangeState',description='Read spell-specific range for a unit using the appropriate client API or spell-book slot. A spell without a range restriction returns applicable=false; otherwise applicable=true and inRange records whether the unit is in range. Unknown or inaccessible observations return nil with a reason.',args={self={type='RMPlatform',description='Rotation Master platform adapter. A dot reference requires addon.Platform as the first argument; a colon call supplies it implicitly.'},id={type='number',description='Spell ID whose range should be checked.'},unit={type='string | nil',description='Unit token, such as target; nil uses target.'},bank={type='string',description='Spell-book scope: spell, pet or any.'}},returns={{type='table | nil',description='Range record with applicable and, when applicable, inRange; nil when unavailable.'},{type='string | nil',description='Availability or validation reason when the record is nil.'}}},
    getCached={module='Functions/cache.lua',member='Functions.cache.getCached',bindingID='builtin:utils.lua:getCached',namespace='Functions.cache',compatibilityNamespaces={'utils'},callName='Functions.cache.getCached',description='Call an observation once per cache and exact argument tuple, including nil results. Pass the evaluation cache to share observations within a recommendation cycle; nil cache calls directly.',args={cache={type='table | nil',description='Evaluation cache, or nil to bypass caching.'},func={type='function | string',description='Function or global function name to call.'},['...']={type='any',description='Arguments forwarded unchanged; types, identity, arity and nil positions distinguish cache entries.'}},returns={type='...',description='All original results, preserving nil positions and return count.'}},
    getRetryCached={module='Functions/cache.lua',member='Functions.cache.getRetryCached',bindingID='builtin:utils.lua:getRetryCached',namespace='Functions.cache',compatibilityNamespaces={'utils'},callName='Functions.cache.getRetryCached',description='Cache an observation after it returns a non-nil value; retry observations whose entire return tuple is nil. Uses the same exact argument keys as getCached.',args={cache={type='table | nil',description='Evaluation cache, or nil to bypass caching.'},func={type='function | string',description='Function or global function name to call.'},['...']={type='any',description='Arguments forwarded unchanged to the observed function.'}},returns={type='...',description='All original results, preserving nil positions and return count.'}},
    compare={module='Functions/values.lua',member='Functions.values.compare',bindingID='builtin:utils.lua:compare',namespace='Functions.values',compatibilityNamespaces={'utils'},callName='Functions.values.compare',description='Compare two values using an RM operator identifier: LESSTHAN, LESSTHANOREQUALS, GREATERTHAN, GREATERTHANOREQUALS, EQUALS, NOTEQUALS or DIVISIBLE. Invalid operators warn and return nil; operands must support the selected Lua operation.',args={operator={type='string',description='RM operator identifier.'},left={type='any',description='Left operand; use numbers for ordering and divisibility.'},right={type='any',description='Right operand; DIVISIBLE requires a nonzero divisor.'}},returns={type='boolean | nil',description='Comparison result, or nil for an unknown operator.'}},
    isin={module='Functions/values.lua',member='Functions.values.isin',bindingID='builtin:utils.lua:isin',namespace='Functions.values',compatibilityNamespaces={'utils'},callName='Functions.values.isin',description='Check whether a table has a non-nil value at a key. A stored false value still counts as present; this does not scan table values.',args={array={type='table',description='Table to inspect.'},value={type='any',description='Lookup key.'}},returns={type='boolean',description='True when array[value] is non-nil.'}},
    playerize={module='Functions/presentation.lua',member='Functions.presentation.playerize',bindingID='builtin:utils.lua:playerize',namespace='Functions.presentation',callName='Functions.presentation.playerize',description='Choose the supplied player value only for the literal player unit token; every other unit selects the nonplayer value. Selected false and nil values are preserved.',args={unit={type='string | nil',description='Unit token to compare with the literal player token.'},player={type='any',description='Value returned when unit is player.'},nonplayer={type='any',description='Value returned for every other unit.'}},returns={type='any',description='The selected value, including false or nil.'}},
    compareString={module='Functions/presentation.lua',member='Functions.presentation.compareString',bindingID='builtin:utils.lua:compareString',namespace='Functions.presentation',callName='Functions.presentation.compareString',description='Format comparison wording with named Boolean alternatives when the operator has a negative form. The primary flag marks the positive form as the primary alternative. Positive operator labels use the captured operator map; negative labels and nullable dispatch retain their live addon APIs.',args={operator={type='string | nil',description='RM comparison operator identifier; missing labels use the operator placeholder.'},left={type='string | number',description='Text or number shown before the comparison wording.'},right={type='string | number',description='Text or number shown after the comparison wording.'},primary={type='boolean | nil',description='Mark the positive wording as the primary named alternative.'}},returns={type='string',description='Comparison text retaining named Boolean alternative markup.'}},
    nullable={module='Functions/presentation.lua',member='Functions.presentation.nullable',bindingID='builtin:utils.lua:nullable',namespace='Functions.presentation',compatibilityNamespaces={'utils'},captureBindings={color='builtin:utils.lua:color'},callName='Functions.presentation.nullable',description='Return a present value unchanged, or a red display placeholder for nil. Use for readable condition labels, not as a boolean fallback.',args={value={type='any',description='Value to display; false is preserved.'},default={type='string | nil',description='Missing-value display text; omitted uses the localized value placeholder.'}},returns={type='any',description='Original non-nil value, or a colored placeholder string.'}},
    nullable_value={module='Functions/presentation.lua',member='Functions.presentation.nullable_value',bindingID='builtin:utils.lua:nullable_value',namespace='Functions.presentation',compatibilityNamespaces={'utils'},captureBindings={color='builtin:utils.lua:color'},callName='Functions.presentation.nullable_value',description='Look up a table key for display, preserving non-nil results; invalid tables, missing keys and nil keys use nullable placeholder text.',args={value={type='any',description='Key to look up.'},array={type='table | nil',description='Display lookup table.'},default={type='string | nil',description='Missing-value display text; omitted uses the localized value placeholder.'}},returns={type='any',description='Original non-nil lookup result, or a colored placeholder string.'}},
    split={module='Functions/text.lua',member='Functions.text.split',bindingID='builtin:utils.lua:split',namespace='Functions.text',compatibilityNamespaces={'utils'},captureBindings={string='builtin:utils.lua:string'},callName='Functions.text.split',description='Split a string into nonempty runs between separator characters. The separator is inserted into a Lua pattern character class; it is not a literal multi-character delimiter. Empty fields are omitted.',args={inputstr={type='string',description='Text to split.'},sep={type='string | nil',description='Lua pattern character-class separator, default %s for whitespace.'}},returns={type='string[]',description='Dense array of nonempty text fields.'}},
    wrap={module='Functions/text.lua',member='Functions.text.wrap',bindingID='builtin:utils.lua:wrap',namespace='Functions.text',compatibilityNamespaces={'utils'},callName='Functions.text.wrap',description='Wrap text at whitespace boundaries near a target column count. Long words are retained intact.',args={str={type='string',description='Text to wrap.'},limit={type='number | nil',description='Target line width, default 72 characters.'}},returns={type='string',description='Text with line breaks inserted at word boundaries.'}},
    trim={module='Functions/text.lua',member='Functions.text.trim',bindingID='builtin:utils.lua:trim',namespace='Functions.text',compatibilityNamespaces={'utils'},callName='Functions.text.trim',description='Remove leading and trailing Lua-pattern whitespace from a string.',args={s={type='string',description='Text to trim.'}},returns={type='string',description='Trimmed text.'}},
    CreateConditionGroup={module='UI/condition_layout.lua',callName='addon:CreateConditionGroup',description='Create a condition field container with RM-owned List, numeric Table and responsive spell-field layouts. It accepts existing condition widgets and legacy custom child widgets; add children with AddChild and attach the group to the callback parent.',args={self={type='RMAddon',description='Rotation Master addon instance (implicit with colon calls).'}},returns={type='RMConditionGroup',description='Condition container supporting SetLayout, AddChild, SetUserData, SetWidth and DoLayout.'}},
    CreateConditionEditBox={module='UI/condition_inputs.lua',callName='addon:CreateConditionEditBox',description='Create a native text input using the condition widget contract. SetLabel, SetText, SetDisabled and SetCallback configure it; OnEnterPressed commits text. Add it to the callback parent with parent:AddChild(widget).',args={self={type='RMAddon',description='Rotation Master addon instance (implicit with colon calls).'}},returns={type='RMConditionInput',description='Text widget supporting label, text, pending-edit and callback methods.'}},
    CreateConditionSlider={module='UI/condition_inputs.lua',callName='addon:CreateConditionSlider',description='Create a native numeric condition input with a slider and typed numeric field. Configure SetSliderValues, SetValue, SetIsPercent and SetCallback; OnValueChanged reports committed values. Add it with parent:AddChild(widget).',args={self={type='RMAddon',description='Rotation Master addon instance (implicit with colon calls).'}},returns={type='RMConditionInput',description='Numeric widget supporting slider bounds, percent display and pending-edit validation.'}},
    CreateConditionDropdown={module='UI/selector.lua',callName='addon:CreateConditionDropdown',description='Create a native condition selector. SetList accepts key-to-label or key-to-entry maps; SetValue selects a key and OnValueChanged reports changes. Add it with parent:AddChild(widget).',args={self={type='RMAddon',description='Rotation Master addon instance (implicit with colon calls).'}},returns={type='RMConditionSelector',description='Selector widget supporting SetList, SetValue, SetLabel, SetDisabled and callbacks.'}},
    CreateConditionCheckBox={module='UI/checkbox.lua',callName='addon:CreateConditionCheckBox',description='Create a native boolean condition control. Configure SetLabel, SetValue, SetDisabled and OnValueChanged; add it with parent:AddChild(widget).',args={self={type='RMAddon',description='Rotation Master addon instance (implicit with colon calls).'}},returns={type='RMConditionCheckBox',description='Checkbox widget with boolean value and callback methods.'}},
    CreateConditionLink={module='UI/condition_display.lua',callName='addon:CreateConditionLink',description='Create native wrapping text with optional leading image and pointer callbacks. SetImage and SetImageSize configure the image; OnEnter, OnLeave and OnClick use the condition callback contract. Add it to the supplied parent; callbacks expire when its lease is released.',args={self={type='RMAddon',description='Rotation Master addon instance (implicit with colon calls).'}},returns={type='RMConditionLink',description='Native interactive text and image control with measured height and disabled state.'}},
    CreateConditionPositionPad={module='UI/condition_position.lua',callName='addon:CreateConditionPositionPad',description='Create a native position pad using the shared directional controls. OnOffsetChanged reports horizontal and vertical direction, whether Center was pressed, and the increment (one, or ten with Shift). SetDisabled controls interaction; add the pad to the supplied parent.',args={self={type='RMAddon',description='Rotation Master addon instance (implicit with colon calls).'}},returns={type='RMConditionPositionPad',description='Native directional pad with center reset and lease-protected callbacks.'}},
    CreateConditionIcon={module='UI/condition_icon.lua',callName='addon:CreateConditionIcon',description='Create a native image control using the condition widget lifecycle. SetImage and SetImageSize choose the texture; SetText optionally adds a caption. OnClick, OnEnter and OnLeave use the shared callback contract. Add the control to the supplied parent.',args={self={type='RMAddon',description='Rotation Master addon instance (implicit with colon calls).'}},returns={type='RMConditionIcon',description='Native image control with label, texture, disabled state and callbacks.'}},
    CreateConditionLabel={module='UI/condition_display.lua',callName='addon:CreateConditionLabel',description='Create native wrapping text that measures its height from its width and font. SetText, SetFont or SetFontObject configure its contents. Add it to the supplied parent so layout can track its measured height.',args={self={type='RMAddon',description='Rotation Master addon instance (implicit with colon calls).'}},returns={type='RMConditionLabel',description='Native wrapping text control with font, color and alignment methods.'}},
    CreateConditionButton={module='UI/condition_display.lua',callName='addon:CreateConditionButton',description='Create a native button using the shared condition widget lifecycle and workbench theme. SetText, SetDisabled and SetCallback configure its label and interaction; OnClick receives the mouse button. Add it to the supplied parent.',args={self={type='RMAddon',description='Rotation Master addon instance (implicit with colon calls).'}},returns={type='RMConditionButton',description='Native button with label, disabled state and lease-protected callbacks.'}},
    Widget_UnitWidget={module='UI/condition_unit.lua',bindingID='builtin:Conditions/common.lua:Widget_UnitWidget',namespace='Conditions.common',callName='addon:Widget_UnitWidget',description='Create a configured unit selector bound to a condition value record. Returns the widget for the caller to add to the condition callback parent.',args={self={type='RMAddon',description='Rotation Master addon instance (implicit with colon calls).'},value={type='table',description='Condition value record updated when a unit is chosen.'},units={type='table',description='Unit key-to-display-name map shown in the selector.'},update={type='function',description='Callback invoked after changing the selected unit.'},field={type='string | nil',description='Value record field to edit; defaults to unit.'}},returns={type='RMConditionSelector',description='Configured unit selector; add it with parent:AddChild(widget).'}},
    Widget_SpellWidget={module='Conditions/common.lua',callName='addon:Widget_SpellWidget',description='Create a spell input with suggestions, validation and spell-link support for custom condition widgets. The update callback owns saving a chosen value; add the returned widget to the callback parent.',args={self={type='RMAddon',description='Rotation Master addon instance (implicit with colon calls).'},spec={type='number',description='Specialization scope used to resolve spell suggestions.'},editbox={type='string',description='Reference input kind, such as Spec_EditBox, used for spell suggestions.'},value={type='table',description='Condition value record containing spell, ranked and disabled fields; updated in place.'},nametoid={type='function',description='Resolver mapping a typed spell name to its ID.'},isvalid={type='function',description='Predicate that validates the proposed spell value.'},update={type='function',description='Callback receiving the committed spell value.'}},returns={type='AceGUIContainer',description='Spell field group containing an action icon, reference input and optional rank control.'}},
    keys={module='Functions/collections.lua',member='Functions.collections.keys',callName='Functions.collections.keys',description='Collect table keys and sort them by their associated values using Lua less-than comparison. This sorts values rather than key names; equal values have no guaranteed key order.',args={array={type='table',description='Table whose values must be mutually comparable.'}},returns={type='table',description='Dense array of keys sorted by associated value.'}},
    spairs={module='Functions/collections.lua',member='Functions.collections.spairs',callName='Functions.collections.spairs',description='Create an iterator over a sorted snapshot of table keys. Default ordering compares keys; a custom order callback receives the original table and two keys. Values are read from the original table when each key is yielded. The legacy iterator ends when the next captured key is nil or false.',args={t={type='table',description='Table to traverse; keys must be mutually comparable when no custom ordering is supplied.'},order={type='function | nil',description='Optional ordering callback called as order(t, leftKey, rightKey).'}},returns={type='function',description='Iterator yielding a captured key and its current table value, or no values when exhausted.'}},
    tomap={module='Functions/collections.lua',member='Functions.collections.tomap',callName='Functions.collections.tomap',description='Copy a table using tostring of each original key as the destination key. Values retain their original identities. Colliding stringified keys overwrite each other in unspecified pairs traversal order.',args={array={type='table',description='Table whose keys should be converted to strings.'}},returns={type='table',description='New table with stringified keys and unchanged values.'}},
    index={module='Functions/collections.lua',member='Functions.collections.index',callName='Functions.collections.index',description='Return the first key whose value equals the supplied value during pairs traversal. Nil or false input tables and absent values return nil. Multiple matching keys have no guaranteed selection order.',args={array={type='table | nil | false',description='Table to search; nil or false returns nil.'},value={type='any',description='Value compared with each table value using Lua equality.'}},returns={type='any',description='Matching key, including a false key, or nil when no match exists.'}},
    tablelength={module='Functions/collections.lua',member='Functions.collections.tablelength',callName='Functions.collections.tablelength',description='Count all entries visited by pairs, including false values and sparse numeric or nonnumeric keys. A nil table has length zero.',args={T={type='table | nil',description='Table to count, or nil for zero.'}},returns={type='number',description='Number of entries visited.'}},
    multiinsert={module='Functions/collections.lua',member='Functions.collections.multiinsert',callName='Functions.collections.multiinsert',description='Insert each value visited by ipairs at its corresponding leading index in the destination array. Existing entries shift after the inserted prefix; traversal stops at the first missing source index.',args={t={type='table',description='Destination array modified in place.'},values={type='table',description='Source array whose ipairs prefix is inserted without copying nested values.'}},returns={type='...',description='No return values. The destination array is modified in place.'}},
    cleanArray={module='Functions/collections.lua',member='Functions.collections.cleanArray',callName='Functions.collections.cleanArray',description='Remove entries in place, preserving only keys listed among except values by default. With invert true, remove listed keys and retain unlisted keys. Without an exception list, the default removes every entry and invert true retains every entry. Nil input does nothing.',args={array={type='table | nil',description='Table to modify, or nil to do nothing.'},except={type='table | nil',description='Optional collection of key values selecting entries; its own keys are ignored.'},invert={type='boolean | nil',description='True removes listed entries; false or nil preserves only listed entries.'}},returns={type='...',description='No return values. The supplied table is modified in place.'}},
    deepcopy={module='Functions/collections.lua',member='Functions.collections.deepcopy',callName='Functions.collections.deepcopy',description='Create a shallow filtered copy despite the historical deepcopy name. Nested values retain their original identities and the source metatable is not copied. By default exclude keys listed among except values; invert true includes only listed keys. Nil input returns nil.',args={array={type='table | nil',description='Table to copy shallowly, or nil.'},except={type='table | nil',description='Optional collection of key values selecting entries; its own keys are ignored.'},invert={type='boolean | nil',description='True includes only listed entries; false or nil excludes listed entries.'}},returns={type='table | nil',description='New shallow filtered table, or nil for nil input.'}},
    compareArray={module='Functions/collections.lua',member='Functions.collections.compareArray',callName='Functions.collections.compareArray',description='Visit entries in both tables and compare each value with the indexed value in the other table using Lua equality. Normal indexing and equality metamethods apply; nested contents are not compared recursively.',args={lhs={type='table',description='First table to compare.'},rhs={type='table',description='Second table to compare.'}},returns={type='boolean',description='True when every visited entry compares equal in both directions.'}},
}
